```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, approx_quantile(c.duration,0.5)/1e6 AS client_p50_ms, approx_quantile(c.duration,0.95)/1e6 AS client_p95_ms, approx_quantile(s.duration,0.95)/1e6 AS rate_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='search' AND c.attr_span_kind='Client' AND c.span_name LIKE 'rate%' GROUP BY c.span_name",
          "claim": "search's GetRates client spans take about 1.5 s p50 and 2.9 s p95, while rate's server spans stay around 1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, approx_quantile(c.duration,0.95)/1e6 AS client_p95_ms FROM abnormal_traces c WHERE c.service_name='search' AND c.attr_span_kind='Client' GROUP BY c.span_name",
          "claim": "Only search's rate call is slow; its geo client spans stay at about 0.7 ms p95 in the incident window."
        },
        {
          "kind": "trace",
          "sql": "SELECT (epoch_ns(s.time) - epoch_ns(c.time))/1e6 AS start_gap_ms, ((epoch_ns(c.time)+c.duration) - (epoch_ns(s.time)+s.duration))/1e6 AS end_gap_ms, c.duration/1e6 AS client_ms, s.duration/1e6 AS server_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='search' AND c.attr_span_kind='Client' AND c.span_name LIKE 'rate%' ORDER BY c.duration DESC LIMIT 10",
          "claim": "Nearly all of the delay occurs before rate receives the request; the response leg is about 0.2 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, avg(value) AS avg_v, max(value) AS max_v FROM abnormal_metrics_sum WHERE metric IN ('k8s.pod.network.errors') AND attr_k8s_pod_name LIKE 'search%' GROUP BY ALL",
          "claim": "search pod shows zero network errors during the incident, so there is no transport-level loss signal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.span_name, s.attr_span_kind, approx_quantile(s.duration,0.95)/1e6 AS p95_ms, count(*) AS n FROM abnormal_traces s WHERE s.service_name IN ('search','frontend') AND s.span_name LIKE 'search.Search/Nearby%' GROUP BY ALL",
          "claim": "search's Nearby server span and frontend's search client span both rise to about 2.9 s p95, while frontend's own work stays small."
        }
      ]
    }
  ]
}
```

